import{_ as i,l,o as a,c as n,v as t,p as s,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"鸽笼原理","description":"","frontmatter":{"title":"鸽笼原理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pigeonhole.md","filePath":"cs/pigeonhole.md","lastUpdated":1789023840000}'),h={name:"cs/pigeonhole.md"};function E(m,e,A,B,_,u){const o=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="鸽笼原理" tabindex="-1">鸽笼原理 <a class="header-anchor" href="#鸽笼原理" aria-label="Permalink to &quot;鸽笼原理&quot;">​</a></h1><div class="epigraph"><p>$n+1$ 只鸽子进 $n$ 个笼子，必有一笼至少两只；证明常常到此为止，不必把那一笼找出来。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/strong-induction">强归纳与结构归纳</a>钉死了如何对每个 \\(n\\) 或每个递归对象证明 \\(P\\)。本课不重写基础步，也不从「概率」另起。<a href="/cs/functions-countable">函数与可数</a>已把有限单射的否定写成一句话。缺口是：后课哈希碰撞、抽屉里的重复，需要可引用的<strong>存在性</strong>格式，以及「至少 \\(k\\) 只」的加强版。归纳证的是全称，鸽笼证的是存在。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限集 \\(A\\) 到更小的有限集 \\(B\\) 没有单射。缺口因此不是新的归纳格式，而是把这句话当引理用：把对象当鸽子、取值当笼子，得出两个对象同值。加强版：\\(\\lvert A\\rvert\\gt m\\lvert B\\rvert\\) 则某笼子至少 \\(m+1\\) 只。</p><p>本课不数「有多少种放法」——排列组合在图与树之后才系统上。<a href="/cs/inclusion-exclusion">容斥</a>给并集的精确计数，鸽笼只管「至少一个非空过载」。生日问题的概率形式要等离散概率；这里只谈必然重复。</p><h3 id="鸽笼不是算法" tabindex="-1">鸽笼不是算法 <a class="header-anchor" href="#鸽笼不是算法" aria-label="Permalink to &quot;鸽笼不是算法&quot;">​</a></h3><p>结论是存在，通常不给出构造。把「必有碰撞」当成已经找到碰撞，后课哈希表的最坏链长会说成已经算出来。也不把无限鸽笼（无穷鸽子有限笼）写进主干：本栏输入默认有限。</p><p><span class="marginnote">Rosen 把鸽笼放在计数之前或之中，强调存在性。可数课的有限单射是否定表述；本课把它变成证题格式，并加上加强版。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明 \\(B\\) 是笼子、\\(A\\) 是鸽子，验证 \\(\\lvert A\\rvert\\gt \\lvert B\\rvert\\)。加强版用反证：若每笼 \\(\\le m\\)，则 \\(\\lvert A\\rvert\\le m\\lvert B\\rvert\\)。典型： \\(n+1\\) 个整数中有两个模 \\(n\\) 同余——笼子是余数 \\(0,\\ldots,n-1\\)。\\(n^2+1\\) 个两两比较的序列里有单调子列，本课不把 Erdős–Szekeres 写完，只表明加强版能走多远。</p>',11)),(a(),s(p,null,{default:r(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIN%5B%22%E6%9C%89%E9%99%90%E5%8D%95%E5%B0%84%E5%90%A6%E5%AE%9A%22%5D%20--%3E%20PH%5B%22%E9%B8%BD%E7%AC%BC%EF%BC%9A%E5%AD%98%E5%9C%A8%E5%90%8C%E7%AC%BC%22%5D%0A%20%20PH%20--%3E%20GEN%5B%22%E5%8A%A0%E5%BC%BA%EF%BC%9A%E8%87%B3%E5%B0%91%20m%2B1%22%5D%0A%20%20GEN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%B9%B6%E9%9B%86%E8%A6%81%E7%B2%BE%E7%A1%AE%E6%95%B0%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>哈希：槽有限、键更多则必有碰撞——这是最坏存在，不是期望链长。后课期望线性性才问「平均几对」。状态机：鸽笼说明足够长的路径必重复某态，从而有环；图的形式下一课之后才有。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入无限公理、Ramsey 的一般着色。也不把抽屉原理写成概率 \\(1\\)：有限必然与「高概率」要分开。容斥、渐近是后续课。</p><p>后课默认：要证「必有两个一样」，先指认笼子；要精确 \\(|A\\cup B|\\)，用容斥。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>鸽子多于笼子则必有一笼至少两只；加强版给至少 \\(m+1\\)。</li><li>只保证存在，不保证构造，也不是概率。</li><li>精确的重叠计数是下一课容斥。</li><li>出处：Rosen, <em>Discrete Mathematics and Its Applications</em>。</li></ul>',7))])}const C=i(h,[["render",E]]);export{v as __pageData,C as default};
